/// C `atoi` semantics: skip leading whitespace, optional +/-, read digits
/// until a non-digit; 0 if there are no digits.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        // clamp to i32 range like typical atoi overflow behavior is UB in C;
        // saturating is a reasonable stand-in and irrelevant for our inputs.
        if val > i32::MAX as i64 {
            val = i32::MAX as i64;
        }
        i += 1;
    }
    if neg {
        -val as i32
    } else {
        val as i32
    }
}

